      ;;
    *) rm -f "$tmpgz" "$tmpbin"; err "Arquitectura no soportada: $arch (soporta amd64/arm64)."; return 1;;
  esac
  base64 -d "$tmpgz.b64" > "$tmpgz" || { rm -f "$tmpgz" "$tmpgz.b64" "$tmpbin"; return 1; }
  rm -f "$tmpgz.b64"
  gzip -dc "$tmpgz" > "$tmpbin" || { rm -f "$tmpgz" "$tmpbin"; return 1; }
  rm -f "$tmpgz"
  if have sha256sum; then
    actual="$(sha256sum "$tmpbin" | awk '{print $1}')"
    [ "$actual" = "$expected" ] || { rm -f "$tmpbin"; err "SHA-256 del motor BHTTP no coincide."; return 1; }
  fi
  install -m 755 "$tmpbin" "$BIN" || { rm -f "$tmpbin"; return 1; }
  rm -f "$tmpbin"
  "$BIN" --self-test >/tmp/sfbhttp-selftest.log 2>&1 || { cat /tmp/sfbhttp-selftest.log; err "El motor Go no pasó autoprueba."; return 1; }
  cat /tmp/sfbhttp-selftest.log
  ok "Motor Go BHTTP $SCRIPT_VERSION instalado y verificado."
}

sysctl_exists(){ sysctl -n "$1" >/dev/null 2>&1; }
apply_tuning(){
  local f=/etc/sysctl.d/99-superflash-bhttp.conf
  : > "$f"
  add(){ sysctl_exists "$1" && { echo "$1 = $2" >> "$f"; sysctl -w "$1=$2" >/dev/null 2>&1 || true; }; }
  add net.ipv4.tcp_tw_reuse 1
  add net.ipv4.tcp_fin_timeout 15
  add net.ipv4.ip_local_port_range "10240 65535"
  add net.core.somaxconn 8192
  add net.ipv4.tcp_max_syn_backlog 8192
  add net.core.netdev_max_backlog 8192
  add net.ipv4.tcp_fastopen 3
  add net.core.rmem_max 8388608
  add net.core.wmem_max 8388608
  ok "Tuning BHTTP aplicado."
}

write_systemd(){
  cat > "/etc/systemd/system/$SERVICE.service" <<EOF
[Unit]
Description=SuperFlash BHTTP SSH transport v$SCRIPT_VERSION
After=network-online.target ssh.service sshd.service
Wants=network-online.target

[Service]
Type=simple
ExecStart=$BIN --listen 0.0.0.0 --port $BHTTP_PORT --backend-host 127.0.0.1 --backend-port $BACKEND_PORT --session-ttl $SESSION_TTL --max-sessions $MAX_SESSIONS --request-timeout 30 --read-wait-ms 8 --sequence-wait 6 --max-requests-per-conn 512
Restart=always
RestartSec=1
LimitNOFILE=131072

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable "$SERVICE" >/dev/null 2>&1 || true
}

write_sysv(){
  cat > "/etc/init.d/$SERVICE" <<EOF
#!/bin/sh
### BEGIN INIT INFO
# Provides:          $SERVICE
# Required-Start:    \$network \$remote_fs
# Required-Stop:     \$network \$remote_fs
# Default-Start:     2 3 4 5
# Default-Stop:      0 1 6
# Short-Description: SuperFlash BHTTP SSH transport
### END INIT INFO
case "\$1" in
 start)
   [ -f "$PIDFILE" ] && kill -0 \$(cat "$PIDFILE") 2>/dev/null && exit 0
   start-stop-daemon --start --background --make-pidfile --pidfile "$PIDFILE" --exec "$BIN" -- --listen 0.0.0.0 --port "$BHTTP_PORT" --backend-host 127.0.0.1 --backend-port "$BACKEND_PORT" --session-ttl "$SESSION_TTL" --max-sessions "$MAX_SESSIONS" --request-timeout 30 --read-wait-ms 8 --sequence-wait 6 --max-requests-per-conn 512 >>"$LOGFILE" 2>&1
   ;;
 stop) start-stop-daemon --stop --retry TERM/5/KILL/2 --pidfile "$PIDFILE" || true; rm -f "$PIDFILE" ;;
 restart) \$0 stop; sleep 1; \$0 start ;;
 status) [ -s "$PIDFILE" ] && kill -0 \$(cat "$PIDFILE") 2>/dev/null ;;
 *) echo "Uso: \$0 {start|stop|restart|status}"; exit 1 ;;
esac
EOF
  chmod 755 "/etc/init.d/$SERVICE"
  update-rc.d "$SERVICE" defaults >/dev/null 2>&1 || true
}
write_service(){ load_conf; if have systemctl && [ -d /run/systemd/system ]; then write_systemd; else write_sysv; fi; }

stop_service(){
  if have systemctl && [ -d /run/systemd/system ]; then systemctl stop "$SERVICE" 2>/dev/null || true
  elif [ -x "/etc/init.d/$SERVICE" ]; then "/etc/init.d/$SERVICE" stop >/dev/null 2>&1 || true; fi
}
start_service(){
  load_conf
  backend_listening || warn "No detecto SSH escuchando en 127.0.0.1:$BACKEND_PORT."
  if have systemctl && [ -d /run/systemd/system ]; then systemctl restart "$SERVICE"
  else "/etc/init.d/$SERVICE" restart; fi
  sleep 1
  if service_active && listening; then ok "BHTTP TCP $BHTTP_PORT ACTIVO → SSH local $BACKEND_PORT"; return 0; fi
  err "BHTTP no quedó escuchando en TCP $BHTTP_PORT."; return 1
}

open_firewall(){
  load_conf
  if have ufw && ufw status 2>/dev/null | grep -q '^Status: active'; then ufw allow "$BHTTP_PORT/tcp" >/dev/null 2>&1 || true; ok "UFW: TCP $BHTTP_PORT permitido."; fi
  if have firewall-cmd && have systemctl && systemctl is-active --quiet firewalld 2>/dev/null; then firewall-cmd --permanent --add-port="$BHTTP_PORT/tcp" >/dev/null 2>&1 || true; firewall-cmd --reload >/dev/null 2>&1 || true; fi
  warn "Si tu proveedor tiene Firewall/Security Group externo, permite TCP $BHTTP_PORT allí."
}

install_server(){
  load_conf; save_conf
  local was=0; service_active && was=1
  stop_service
  write_binary || return 1
  rm -rf "$OLD_APP_DIR" 2>/dev/null || true
  : > "$LOGFILE"; chmod 640 "$LOGFILE" 2>/dev/null || true
  echo "version=$SCRIPT_VERSION engine=go installed=$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$MARKER"
  write_service; apply_tuning
  if [ "$was" -eq 1 ]; then start_service || return 1; fi
  ok "Servidor BHTTP v$SCRIPT_VERSION instalado/reparado. SIN TOKEN."
}

configure_port(){
  local p="$1"; validate_port "$p" || { err "Puerto inválido: $p"; return 1; }
  load_conf
  if listening_port "$p" && ! service_active; then
    err "TCP $p está ocupado por otro proceso."; have ss && ss -lntp 2>/dev/null | grep -E "[:.]${p}[[:space:]]" || true; return 1
  fi
  BHTTP_PORT="$p"; save_conf
  installed || install_server || return 1
  write_service; start_service || return 1; open_firewall
  echo
  echo -e "${BOLD}Generador SuperFlash:${NC}"
  echo "  Tipo             : BHTTP"
  echo "  Host/IP          : IP pública de esta VPS"
  echo "  Puerto           : $BHTTP_PORT"
  echo "  Usuario/Password : usuario SSH/PAM normal de la VPS"
  echo "  Slots subida     : 16"
  echo "  Slots descarga   : 32"
}

configure_backend(){
  load_conf; read -r -p "Puerto SSH/PAM interno [$BACKEND_PORT]: " p; p="${p:-$BACKEND_PORT}"
  validate_port "$p" || { err "Puerto inválido."; return 1; }
  BACKEND_PORT="$p"; save_conf; installed && { write_service; start_service || true; }
  ok "Backend SSH: 127.0.0.1:$BACKEND_PORT"
}

show_status(){
  header; load_conf
  echo "Configuración : $CONF"
  echo "Motor         : $($BIN --version 2>/dev/null || echo no-instalado)"
  echo "BHTTP externo : 0.0.0.0:$BHTTP_PORT/TCP"
  echo "SSH backend   : 127.0.0.1:$BACKEND_PORT/TCP"
  echo "Sesión TTL    : $SESSION_TTL s"
  echo "Máx sesiones  : $MAX_SESSIONS"
  echo "Persistencia  : 512 requests/conexión física"
  echo "Backend SSH   : $(backend_listening && echo ESCUCHANDO || echo NO-DETECTADO)"
  echo
  if have ss; then ss -lntp 2>/dev/null | grep -E "[:.]($BHTTP_PORT|$BACKEND_PORT)[[:space:]]" || true
  elif have netstat; then netstat -lntp 2>/dev/null | grep -E "[:.]($BHTTP_PORT|$BACKEND_PORT)[[:space:]]" || true; fi
  echo
  if have systemctl && [ -d /run/systemd/system ]; then systemctl --no-pager --full status "$SERVICE" 2>/dev/null | sed -n '1,20p' || true; fi
}
show_logs(){ if have systemctl && [ -d /run/systemd/system ]; then journalctl -u "$SERVICE" --no-pager -n 120 2>/dev/null || true; else tail -n 120 "$LOGFILE" 2>/dev/null || true; fi; }
self_test(){ installed || { err "Instala el servidor primero."; return 1; }; "$BIN" --self-test && ok "Autoprueba motor BHTTP PASS."; }

uninstall_server(){
  warn "Elimina SOLO el servidor BHTTP; no elimina usuarios SSH."; read -r -p "¿Continuar? [s/N]: " a
  case "${a:-n}" in s|S|y|Y) ;; *) return 0;; esac
  stop_service
  if have systemctl && [ -d /run/systemd/system ]; then systemctl disable "$SERVICE" >/dev/null 2>&1 || true; rm -f "/etc/systemd/system/$SERVICE.service"; systemctl daemon-reload
  else rm -f "/etc/init.d/$SERVICE"; update-rc.d -f "$SERVICE" remove >/dev/null 2>&1 || true; fi
  rm -f "$BIN" "$MARKER" "$CONF" "$PIDFILE"; rm -rf "$OLD_APP_DIR"; ok "Servidor BHTTP eliminado."
}

menu(){
 while true; do
  header
  echo " 1) Instalar/ACTUALIZAR motor BHTTP v$SCRIPT_VERSION (SIN TOKEN)"
  echo " 2) Abrir/iniciar BHTTP TCP 80"
  echo " 3) Abrir BHTTP en puerto manual"
  echo " 4) Configurar puerto SSH backend (22 por defecto)"
  echo " 5) Estado/diagnóstico"
  echo " 6) Ver logs"
  echo " 7) Autoprueba local BHTTP"
  echo " 8) Reiniciar servidor"
  echo " 9) Detener servidor"
  echo "10) Aplicar tuning BHTTP"
  echo "11) Desinstalar servidor BHTTP"
  echo " 0) Salir"
  echo
  read -r -p "Opción: " op
  case "$op" in
   1) install_server; pause;;
   2) configure_port 80; pause;;
   3) read -r -p "Puerto BHTTP TCP: " p; configure_port "$p"; pause;;
   4) configure_backend; pause;;
   5) show_status; pause;;
   6) show_logs; pause;;
   7) self_test; pause;;
   8) installed && { write_service; start_service; } || err "No instalado"; pause;;
   9) stop_service; ok "Servidor detenido."; pause;;
   10) apply_tuning; pause;;
   11) uninstall_server; pause;;
   0) exit 0;;
   *) warn "Opción inválida"; sleep 1;;
  esac
 done
}

main(){
 require_root; load_os; load_conf
 case "${1:-}" in
  --install) install_server; configure_port "${2:-80}";;
  --open-port) configure_port "${2:-80}";;
  --status|--diagnose) show_status;;
  --self-test) self_test;;
  --help|-h) echo "Uso: bash $0 [--install [puerto]|--open-port PUERTO|--status|--self-test]";;
  "") menu;;
  *) err "Parámetro desconocido: $1"; exit 2;;
 esac
}
main "$@"
